import app from 'flarum/forum/app';
import Modal from 'flarum/common/components/Modal';
import Button from 'flarum/common/components/Button';
import Icon from 'flarum/common/components/Icon';
import Link from 'flarum/common/components/Link';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
import { gameUrl, lineName, placeName, statusOf, t, MEDALS } from '../api';
import GameState, { useClock } from '../state';
import Card from './Card';
import { Person } from './Panels';
import { Clock, StatusPill } from './parts';
/**
 * The card over a watch-along discussion: mark it without leaving the
 * thread. Full-screen on a phone (Flarum's modals are), so cells stay big.
 */
export default class CardModal extends Modal {
  oninit(vnode) {
    super.oninit(vnode);
    this.state = GameState.for(this.attrs.id);
    this.stop = this.state.watch();
    this.stopClock = useClock();
  }
  onremove(vnode) {
    super.onremove(vnode);
    this.stop();
    this.stopClock();
  }
  className() {
    return 'BingoCardModal';
  }
  title() {
    return this.state.data?.game.title ?? t('hub.title');
  }
  content() {
    const state = this.state;
    const data = state.data;
    if (!data) return m("div", {
      className: "Modal-body"
    }, state.error ? m("p", null, t('errors.bingo_not_found')) : m(LoadingIndicator, null));
    const game = data.game;
    const recent = data.claims.slice(0, 3);
    return m("div", {
      className: "Modal-body"
    }, m("div", {
      className: "BingoCardModal-kicker"
    }, m(StatusPill, {
      game: game
    }), m(Clock, {
      game: game
    }), m("span", {
      className: "BingoCardModal-players"
    }, m(Icon, {
      name: "fas fa-users"
    }), " ", t('game.players', {
      count: game.players
    }))), data.me ? m(Card, {
      state: state
    }) : this.join(), !!recent.length && m("ul", {
      className: "BingoCardModal-calls"
    }, recent.map(claim => m("li", null, m(Person, {
      id: claim.user
    }), " ", t('calls.called', {
      line: lineName(claim.line)
    }), ' ', claim.status === 'accepted' && claim.place ? `${MEDALS[claim.place - 1]} ${placeName(claim.place)}` : null))), m("p", {
      className: "BingoCardModal-more"
    }, m(Link, {
      href: gameUrl(game),
      onclick: () => this.hide()
    }, t('card.open_page'), " ", m(Icon, {
      name: "fas fa-arrow-right"
    }))));
  }
  join() {
    const state = this.state;
    if (state.data.game.host === Number(app.session.user?.id())) return m("p", {
      className: "BingoCardModal-note"
    }, t('join.hosting'));
    if (statusOf(state.data.game) === 'finished') return m("p", {
      className: "BingoCardModal-note"
    }, t('join.over'));
    if (!app.session.user) {
      return m(Button, {
        className: "Button Button--primary Button--block",
        icon: "fas fa-right-to-bracket",
        onclick: () => app.modal.show(() => flarum.reg.asyncModuleImport('flarum/forum/components/LogInModal'))
      }, t('join.log_in'));
    }
    if (!app.forum.attribute('bingoCanPlay')) return m("p", {
      className: "BingoCardModal-note"
    }, t('join.watch_only'));
    return m("div", {
      className: "BingoCardModal-join"
    }, m("p", null, t('join.help', {
      count: state.data.squares.length
    })), m(Button, {
      className: "Button Button--primary Button--block",
      icon: "fas fa-table-cells",
      loading: state.busy,
      onclick: () => state.join()
    }, t('join.button')));
  }
}
flarum.reg.add('ernestdefoe-bingo', 'forum/components/CardModal', CardModal);